import type {DownloadCardData} from '@github-ui/download-cards/DownloadCard/DownloadCard'
import github_desktop from '../assets/github_desktop.svg'
import vscode_copilot from '../assets/vscode_copilot.svg'
import {updateSetting} from './settings-helper'
import {DashboardDismissalSettings} from '../constants/dashboard-settings'
import type {AnalyticsEvent} from '@github-ui/use-analytics'
import type {RecommendationDismissals} from '../types/recommendations-types'

export function getRecommendationCards(
  recommendationDismissals: RecommendationDismissals,
  sendClickAnalyticsEvent: (
    payload?:
      | {
          [key: string]: unknown
        }
      | AnalyticsEvent
      | undefined,
  ) => void,
): DownloadCardData[] {
  return [
    {
      dismissed: recommendationDismissals.desktopDismissed,
      title: 'GitHub for Desktop',
      description:
        "Whether you're new to Git or a seasoned user, GitHub Desktop enables collaboration from your desktop and can simplify your development workflow.",
      icon: github_desktop,
      href: 'https://desktop.github.com/',
      openInNewTab: false,
      analytics: {
        category: 'alt_zero_user_dashboard',
        action: 'click.recommendations.github_desktop.download',
      },
      onDismiss: () => {
        updateSetting(DashboardDismissalSettings.Desktop, true)

        sendClickAnalyticsEvent({
          category: 'alt_zero_user_dashboard',
          action: 'click.recommendations.github_desktop.dismiss',
        })
      },
    },
    {
      dismissed: recommendationDismissals.vscodeDismissed,
      title: 'Visual Studio Code with Copilot',
      description:
        'Customizable. Contextual. AI-powerful. GitHub Copilot can use your code and custom instructions to code the way you prefer.',
      icon: vscode_copilot,
      href: 'https://code.visualstudio.com/',
      openInNewTab: true,
      analytics: {
        category: 'alt_zero_user_dashboard',
        action: 'click.recommendations.vscode_copilot.download',
      },
      onDismiss: () => {
        updateSetting(DashboardDismissalSettings.VSCode, true)

        sendClickAnalyticsEvent({
          category: 'alt_zero_user_dashboard',
          action: 'click.recommendations.vscode_copilot.dismiss',
        })
      },
    },
  ]
}
